  async function loadBridge(){const cached=readTaskCache();if(cached)acceptTaskProjection(cached);try{const [inbox,tasks,outbox,notifications]=await Promise.all([request('/api/gpt-bridge/inbox'),request('/api/task-projection'),request('/api/gpt-bridge/outbox'),request('/api/gpt-bridge/notifications')]);const items=inbox.items??[];bridgeInbox=items;acceptTaskProjection(tasks);bridgeOutbox=outbox.items??[];await refreshComposerCanonicalResult();const notificationItems=notifications.items??[];if(!bridgeNotificationInitialized){bridgeSeenNotificationIds=new Set(notificationItems.map((item:any)=>item.id));bridgeNotificationInitialized=true}else{const feedbackOwnerRunId=runtimeFeedbackRunId??selectedRunId;const incoming=notificationItems.find((item:any)=>!bridgeSeenNotificationIds.has(item.id)&&(!feedbackOwnerRunId||item.runId===feedbackOwnerRunId));if(incoming){bridgeSeenNotificationIds.add(incoming.id);setFeedback({state:incoming.phase==='FAILED'?'ERROR':incoming.phase==='STOPPED'?'BLOCKED':'SUCCESS',title:incoming.title,message:incoming.message,code:`TERMINAL_${incoming.phase}`})}}notificationItems.forEach((item:any)=>bridgeSeenNotificationIds.add(item.id));if(!bridgeInboxInitialized){bridgeSeenInboxIds=new Set(items.map((item:any)=>item.id));if(selectedInboxId&&!items.some((item:any)=>item.id===selectedInboxId))selectedInboxId=null;bridgeInboxInitialized=true}}catch{/* bridge state is shown as unavailable by the service status */}}
