      {#if !(globalWorkspace&&['PR','TASK'].includes(activeGlobalTab))}<EntityHeader context={centerContext} statusOverride={presentationStatus(centerContext.type==='milestone'?projectedLifecycleText(uiLifecycleReadModel,'MILESTONE',centerContext.id,'milestone.lifecycle'):contextHeaderLifecycle)} statusLabelOverride={centerContext.type==='milestone'?projectedLifecycleText(uiLifecycleReadModel,'MILESTONE',centerContext.id,'milestone.lifecycle'):contextHeaderLifecycle} description={selectedDescription} onSave={saveDescription}/>{/if}
