onical Task 与 Run 上下文。</p></section>{/if}{:else if selectedTaskActiveTab==='证据'}{#if selectedTaskWorkPackageContext}<section data-testid="task-evidence-content"><EntityEvidencePanel context={selectedTaskWorkPackageContext} repository={snapshot.repository.value} {codexInfo} runtimeOverride={selectedTaskRuntime}/></section>{:else}<section class="tab-error" data-testid="task-evidence-unmapped"><strong>无映射实体证据</strong><p>{selectedTaskRuntimeId??'当前 Task 尚未绑定 Run'}</p></section>{/if}{:else if selectedTaskActiveTab==='授权'}{#if selectedTaskWorkPackageContext}<AuthorizationWorkspace context={selectedTaskWorkPackageContext} repository={snapshot.repository.value?.repository??'不可用'}/>{:else}<section class="tab-error" data-testid="task-authorization-unmapped"><strong>当前 Task 未绑定 Work Package</strong><p>没有可投影的 Work Package 授权。</p></section>{/if}{/if}</EntityOperationsWorkspace>{#if selectedTaskWorkPackageContext}<section class="wp-delivery-section" data-testid="task-delivery-section"><div class="section-label"><span>Delivery</span><small>Task-bound Work Package context</small></div><DeliveryContextPanel context={selectedTaskWorkPackageContext} repository={snapshot.repository.value?.repository??'UNAVAILABLE'} projection={selectedTaskWorkPackageId===selectedEntity.id?deliveryProjection:null}/></section>{/if}{:else}<GlobalTaskView center groups={globalTaskGroups} {legacyTaskCount} {selectedTaskId} onSelectTask={selectCanonicalTask} onCopyTaskResult={copyTaskRowResult} onOpenWorkspace={openGlobalWorkspace} onOpenPrWorkspace={openGlobalPrWorkspace}/>{/if}
      {:else if globalWorkspace && activeGlobalTab==='WP'}
        <GlobalWpWorkspace records={globalWorkPackages} nodes={globalMilestones} selectedId={selectedEntity.type==='work_package'?selectedEntity.id:null} onSelect={navigateGlobalEntity} onRefresh={refreshWorkPackageProjection}/>
      {:else if globalWorkspace && activeGlobalTab==='BLUEPRINT'}
        <GlobalBlueprintWorkspace milestones={globalMilestones} workPackages={globalWorkPackages} pullRequests={snapshot.pullRequests.value??[]} tasks={globalTasks} currentMilestone={globalCurrentMilestone} currentWorkPackage={globalCurrentWorkPackage} currentPhase={globalCurrentPhase} ownerWaiting={globalOwnerWaiting}/>
