="pull_request" entityId={context.id} runtime={context.runtime} history={scopedRuntimeHistory} selectedRunId={selectedRunId} selectedInboxId={selectedInboxId} workPackage={null} writerLock={{status:'NOT_HELD',scope:'repository'}} bridgeInbox={scopedBridgeInbox} bridgeOutbox={bridgeOutbox} bridgePayload={bridgePayload} instructionState={instructionState} tasks={scopedTaskRecords} {selectedTaskId} onSelectTask={selectCanonicalTask} showComposer={false} onCopyResult={executionActions.copyResult} onCopyExample={copyBridgeExample} onLaunch={launchBridge} onCopyReport={(report)=>navigator.clipboard?.writeText(JSON.stringify(report,null,2))} onSelectRun={(id)=>selectedRunId=id}/>{:else if activeTab==='UAT'}<HumanUatWorkspace context={context} repository={snapshot.repository.value?.repository??'local'} record={prUatRecord} onSave={saveHumanUat} onNavigate={(tab)=>activeTab=tab}/>{:else if activeTab==='证据'}<PrEvidencePanel context={context}/>{:else}<div class="pr-tab-view" data-testid="pr-tab-content" data-pr-tab={prTab.tab}>{#if prTab.tab==='概览'}<PrOwnerActionZone context={context} {busy} onAction={runAction} onNavigate={(tab)=>activeTab=tab}/>{/if}<div class="section-label"><span>{prTab.title}</span><small>{prTab.tab}</small></div>{#if prTab.description}<p class="pr-tab-description">{prTab.description}</p>{/if}<div class="runtime-list">{#each prTab.rows as row}<div><span>{row[0]}</span><b>{row[1]}</b></div>{/each}</div></div>{/if}</EntityOperationsWorkspace></section>{/if}
      <div class="composer-overlay-tail-spacer" data-testid="composer-overlay-tail-spacer" aria-hidden="true" style={`--aicc-composer-overlay-height:${composerHeight}px`}></div>
    </div></div><div class="global-composer-dock-lane" data-testid="global-composer-dock-lane"><GlobalExecutionComposerDock payload={bridgePayload} {instructionState} contextLabel={currentContextPrimaryLabel} copyResultAvailable={Boolean(composerCopyResult)} onPayloadChange={updateBridgePayload} onPaste={pasteInstruction} onSubmitStart={beginComposerExecution} onImport={importInstruction} onProfileChange={syncGlobalExecutionProfile} onCopyResult={copyComposerResult} onHeightChange={updateComposerHeight}/></div></main>
    <div class="resize-handle" onpointerdown={(event)=>resize('right',event)} role="separator" aria-label="调整状态宽度"></div>
  <aside class:drawer-open={drawer==='status'} class="status panel">{#if milestoneOverviewId&&context.type==='work_package'}<WpRightContextInspector {context} onClear={()=>milestoneOverviewId&&select(milestoneOverviewId)} onOpen={openSelectedWorkPackageWorkspace}/>{:else if activeGlobalTab==='TASK'&&selectedTask}<TaskRightContextInspector task={selectedTask} runtime={selectedTaskRuntime} report={selectedTaskReport} resultProjection={selectedTaskResultProjection} onClose={clearSelectedTask} onViewWorkPackage={(id)=>navigateGlobalEntity({type:'work_package',id})}/>{:else if activeGlobalTab==='PR'&&!selectedPrNavigationId}<div data-testid="pr-evidence-empty"><div class="panel-header"><div><span class="kicker">03 / EVIDENCE</span><h2>状态与证据</h2></div></div><p class="evidence-intro">选择一个 PR 后显示状态与证据。</p></div>{:else if activeGlobalTab==='PR'&&selectedEntity.type==='pull_request'}<div data-testid="pr-selected-right-inspector"><div class="panel-header"><div><span class="kicker">03 / EVIDENCE</span><h2>状态与证据</h2></div></div><EntityEvidencePanel {context} repository={snapshot.repository.value} {codexInfo} runtimeOverride={displayRuntime}/></div>{:else}<div class="panel-header"><div><span class="kicker">03 / EVIDENCE</span><h2>状态与证据</h2></div><div class="status-tools"><button class="service-action" onclick={()=>runAction('REFRESH')}>刷新状态</button>{#if context.type==='work_package'}<button class="service-action" onclick={()=>runAction('SAFE_MAIN_SYNC')}>同步本地 main</button>{/if}</div></div><EntityEvidencePanel {context} repository={snapshot.repository.value} {codexInfo} runtimeOverride={displayRuntime}/>{/if}</aside>
  </div>
</div>

<style>
  .header-execution-selector{display:flex;align-items:center;gap:5px;color:var(--text-3);font:10px var(--font-tech);white-space:nowrap}.header-execution-selector select{max-width:118px;padding:4px 5px;border:1px solid var(--border-soft);border-radius:5px;background:var(--surface);color:var(--text-1);font:11px var(--font-ui)}.pr-navigation-footer{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:3px 8px;margin-top:auto;white-space:normal}.pr-navigation-footer span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.pr-navigation-footer span:first-child{grid-column:1 / -1}.pr-navigation-footer button{grid-column:2;grid-row:2;width:22px;height:22px;padding:0;border:0;border-radius:5px;background:transparent;color:var(--text-2);cursor:pointer}.pr-navigation-footer button:hover{background:var(--surface-soft);color:var(--text-1)}.pr-detail-empty{display:grid;gap:12px;padding:24px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface)}.pr-detail-empty p{margin:0;color:var(--text-2);font-size:13px}
</style>
